//! Whole frozen policy/parse comparisons; no native answer feeds the originals.
use super::*;
#[path="allow_parser_original.rs"]mod original_parser;
#[cfg(feature="legacy-sem")]#[path="allow_annotations_original.rs"]mod original;
struct Probe{left:usize,polls:usize,fail:usize,denied:bool}
impl Control for Probe{type Error=std::io::Error;const CHECKED:bool=true;fn checkpoint(&mut self)->Result<(),Self::Error>{if self.denied{return Err(std::io::ErrorKind::OutOfMemory.into())}self.polls+=1;if self.polls==self.fail{Err(std::io::Error::from_raw_os_error(1450))}else{Ok(())}}fn reserve(&mut self,bytes:usize)->Result<(),Self::Error>{self.left=match self.left.checked_sub(bytes){Some(left)=>left,None=>{self.denied=true;return Err(std::io::ErrorKind::OutOfMemory.into())}};Ok(())}fn overflow(&mut self)->Self::Error{self.denied=true;std::io::ErrorKind::OutOfMemory.into()}fn allocation_failed(&mut self)->Self::Error{self.denied=true;std::io::ErrorKind::OutOfMemory.into()}}
fn probe()->Probe{Probe{left:16*1024*1024,polls:0,fail:usize::MAX,denied:false}}
const CASES:&[&str]=&["not an annotation","// ALLOW():","// ALLOW(scheduler)","// ALLOW(missing, scheduler/BLOCKING_IO): world.Export() is a blocking external call","// ALLOW(handlers): see above for the reason for this operation","// ALLOW(handlers): this wave F3 keeps a formerly blocking operation","// ALLOW(handlers): this is kept until M1a lands in the tree","// ALLOW(handlers): tiny","// ALLOW(scheduler, handlers): world.Export() is a blocking external call","// ALLOW(scheduler/ONE, scheduler/TWO): preserve original duplicate code replacement",r"#define X /* ALLOW(scheduler): preserve this macro invocation for external callers */ \","// ALLOW(@): malformed syntax must retain original complaint order","// ALLOW(scheduler): café Δοκιμή deliberately retains a Unicode reason"];
#[test]fn frozen_annotation_parser_matches_all_fields_and_duplicate_code_replacement(){for line in CASES{let old=original_parser::parse(line);let new=allow::parse_with(line,&mut probe()).unwrap();assert_eq!(new.as_ref().map(|a|(&a.names,&a.codes,&a.reason,a.has_colon)),old.as_ref().map(|a|(&a.names,&a.codes,&a.reason,a.has_colon)),"{line}");}}
#[test]fn controlled_annotation_first_io_quota_and_callback_abort_never_return_partial_success(){let known=["scheduler".to_owned()].into_iter().collect();let line="// ALLOW(missing): world.Export() is a blocking external call";let mut rows=Vec::new();let error=validate_line(&known,7,line,&mut probe(),|_,_,message|{rows.push(message);Err(std::io::Error::from_raw_os_error(1450))}).unwrap_err();assert_eq!(error.raw_os_error(),Some(1450));assert_eq!(rows.len(),1);let mut tiny=Probe{left:0,..probe()};let error=validate_line(&known,7,line,&mut tiny,|_,_,_|panic!("denial must precede output")).unwrap_err();assert_eq!(error.kind(),std::io::ErrorKind::OutOfMemory);let mut io=Probe{fail:2,..probe()};assert_eq!(validate_line(&known,7,line,&mut io,|_,_,_|panic!("first IO must precede output")).unwrap_err().raw_os_error(),Some(1450));assert!(validate_line(&known,7,line,&mut probe(),|_,_,_|Ok(())).is_ok());}
#[cfg(feature="legacy-sem")]
#[test]fn complete_frozen_allow_validation_and_unused_digest_quiet_order_match(){
 use crate::{lint::{Registry,Cx,Sink,AllowUse},tree::{Tree,SourceFile}};
 let known:BTreeSet<_>=["scheduler","handlers","check_grep","doc_snippets"].into_iter().map(str::to_owned).collect();original::set_known(known.clone());let mut registry=Registry::default();original::register(&mut registry);let lint=registry.find("allow_annotations").unwrap();
 let mut files=vec![SourceFile::from_text("code/a.dm",&CASES.join("\n")),SourceFile::from_text("maps/b.dm","// ALLOW(handlers): world.Export() is a blocking external call\n// ALLOW(scheduler): world.Export() is a blocking external call\n"),SourceFile::from_text("code/first.dm","// ALLOW(@): malformed marker still maps an extra digest\n")];files.sort_by(|a,b|a.rel.cmp(&b.rel));let tree=Tree::from_files(files);let scope=crate::scopes::LintScope::default();
 for file in &tree.files{let cx=Cx{ fixture:None,tree:&tree,meta:lint.meta(),scope:&scope};let mut old=Sink::new();old.cur=file.rel.clone();lint.scan_file(&cx,file,&mut old);let mut actual=Sink::new();actual.cur=file.rel.clone();for(number,line)in file.raw().numbered(){validate_line(&known,number,line,&mut probe(),|rule,line,message|{actual.site_msg(rule,line,message);Ok(())}).unwrap();}assert_eq!(actual.sites,old.sites,"{}",file.rel);assert_eq!(actual.notes,old.notes);assert_eq!(actual.allow_used,old.allow_used);}
 let usage=vec![AllowUse{name:"scheduler".into(),rel:"maps/b.dm".into(),line:2,code:String::new()}];let extra=vec![("handlers".into(),"collision".into(),1),("missing".into(),"absent".into(),99)];let digest=|relative:&str|if relative=="code/first.dm"||relative=="maps/b.dm"{"collision".to_owned()}else{relative.to_owned()};
 for used in [&[][..],usage.as_slice()]{for extra in [&[][..],extra.as_slice()]{let old=original::unused(&tree,used,extra,&digest);let facts:Vec<_>=tree.files.iter().map(|file|annotations(file.raw().numbered(),&mut probe()).unwrap()).collect();let rows:Vec<_>=tree.files.iter().zip(&facts).map(|(file,annotations)|AnnotationFile{relative:&file.rel,has_marker:file.text().contains("ALLOW("),annotations}).collect();let actual=unused(&known,used,extra,&rows,&digest,&mut probe()).unwrap();assert_eq!(actual,old);}}
}

#[cfg(feature="legacy-sem")]
#[test]fn preport_actual_complete_registry_emits_independent_metadata_evidence(){
 let registry=crate::run::registry();let names:BTreeSet<String>=registry.lints.iter().flat_map(|lint|lint.meta().allow.iter().map(|name|(*name).to_owned())).collect();assert!(!names.is_empty());let fields:Vec<_>=registry.lints.iter().map(|lint|{let meta=lint.meta();serde_json::json!({"name":meta.name,"allow":meta.allow})}).collect();let record=serde_json::json!({"engine_hash":env!("DQ_ENGINE_HASH"),"names":names,"registered_fields":fields});println!("OLD_ALLOW_REGISTRY={record}");
}
